import torch, numpy as np, hashlib
path = '/challenge/attachment/maze.pt'
class Maze(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.maze = torch.nn.Linear(42,42)
obj = torch.load(path, map_location='cpu', weights_only=False)
maze_int = obj.maze.weight.detach().cpu().numpy().astype(int)
start = tuple(map(int, np.argwhere(maze_int==2)[0]))
end = tuple(map(int, np.argwhere(maze_int==3)[0]))
rows, cols = maze_int.shape
mask = maze_int!=0
from collections import deque

def bfs(order):
    dirs = {'U':(-1,0), 'D':(1,0), 'L':(0,-1), 'R':(0,1)}
    q = deque([start])
    visited = np.full((rows, cols), False)
    visited[start] = True
    prev = {}
    while q:
        r,c = q.popleft()
        if (r,c)==end:
            break
        for m in order:
            dr,dc = dirs[m]
            nr,nc = r+dr, c+dc
            if 0<=nr<rows and 0<=nc<cols and not visited[nr,nc] and mask[nr,nc]:
                visited[nr,nc]=True
                prev[(nr,nc)] = (r,c,m)
                q.append((nr,nc))
    # reconstruct
    cur=end
    moves=[]
    while cur!=start:
        r,c,m = prev[cur]
        moves.append(m)
        cur=(r,c)
    return ''.join(reversed(moves))

orders = [list('UDLR'), list('URDL'), list('RDLU'), list('DLUR'), list('LRUD')]
for o in orders:
    p=bfs(o)
    print('order', ''.join(o), len(p), p[:10]+'...')
    print('md5', hashlib.md5(p.encode()).hexdigest())

